'use strict';

const fs = require('node:fs/promises');
const path = require('node:path');

const ENDPOINT = process.env.STATUS_ENDPOINT || 'http://127.0.0.1:54686/status';
const OUTPUT_FILE = path.join(__dirname, 'results', 'status.json');

async function main() {
  const response = await fetch(ENDPOINT);
  if (!response.ok) {
    throw new Error(`Request failed: ${response.status} ${response.statusText}`);
  }

  const body = await response.json();
  const status = body.status ?? response.status;

  await fs.mkdir(path.dirname(OUTPUT_FILE), { recursive: true });
  await fs.writeFile(OUTPUT_FILE, `${JSON.stringify({ status }, null, 2)}\n`);

  console.log(`Wrote status=${status} to ${OUTPUT_FILE}`);
}

main().catch((error) => {
  console.error(error.message);
  process.exit(1);
});

